using System;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class SteamUnavailableTests {
 public static void Run(){var method=typeof(SteamLauncherServices).GetMethod("ParseSubscribedUgc",BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Static);if(method==null)throw new Exception("FAIL: inaccessible subscribed item does not invalidate entire subscription list");byte[] bytes=new byte[9776];Array.Copy(BitConverter.GetBytes(42UL),0,bytes,0,8);Array.Copy(BitConverter.GetBytes(15),0,bytes,8,4);var j=new JavaScriptSerializer();var row=j.Deserialize<Dictionary<string,object>>(j.Serialize(method.Invoke(null,new object[]{bytes,5U,"",new ulong[0]})));if(Convert.ToString(row["id"])!="42"||!Convert.ToBoolean(row["unavailable"])||!Convert.ToBoolean(row["subscribed"])||!Convert.ToBoolean(row["downloaded"]))throw new Exception("FAIL: inaccessible subscriptions retain ID/availability/file-state evidence");Console.WriteLine("PASS: inaccessible subscribed metadata remains visible without authorizing download");}
 public static int Main(){try{Run();return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
}}
